interface.definition:
a!localVariables(
  local!isNewVersion: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    true,
    if(
      todatetime(ri!nomination.createdOn) > #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      false
    )
  ),
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
  showWhen: local!isNewVersion,
  contents: {
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_gridField_v1"(
                  /*label: "Uploaded Attachments",*/
                  labelPosition: "ABOVE",
                  data: ri!documents,
                  emptyGridMessage: "No Attachments Uploaded",
                  columns: {
                    #"SYSTEM_SYSRULES_gridColumn"(
                      label: "Document Name",
                      value: document(fv!row.docId,"name"),
                      align: "CENTER"
                    ),
                    #"SYSTEM_SYSRULES_gridColumn"(
                      label: "Extension",
                      value: upper(document(fv!row.docId,"extension")),
                      align: "CENTER",
                      width: "NARROW_PLUS"
                    ),
                    #"SYSTEM_SYSRULES_gridColumn"(
                      label: "Download",
                      align: "CENTER",
                      width: "NARROW_PLUS",
                      value: #"SYSTEM_SYSRULES_richTextDisplayField"(
                        value: #"SYSTEM_SYSRULES_richTextIcon"(
                          icon: "download",
                          color: "ACCENT",
                          link:  #"SYSTEM_SYSRULES_documentDownloadLink"(
                            label:  document(fv!row.docId,"name"),
                            document: todocument(fv!row.docId)
                          ),
                          linkStyle: "STANDALONE"
                        )
                      )
                    )
                  }
                )
              }
            )
          }
        )
      },
      height: "AUTO",
      style: "NONE",
      marginBelow: "STANDARD"
    )
  }
)
)
